from membership_chapters import membership_chapter, membership_state_chapter
"""Полная русская версия; фрагменты C# берутся из компилируемого проекта."""
from build import (p, h, ul, ol, callout, table, code, excerpt, source_link,
                   path_tree, flow, quorum_lab, memory_lab, EXAMPLES)


def chapters():
    book = []
    add = lambda ident, title, body: book.append((ident, title, body))

    add("orientation", "Какое приложение мы создаём", p(
        "Raft.Net8 — <strong>встраиваемая библиотека распределённого консенсуса</strong>. Вы запускаете отдельный процесс для каждой реплики, передаёте ему транспорт и детерминированное приложение, а затем отправляете команды избранному лидеру. Библиотека упорядочивает и реплицирует команды. Ваш код определяет смысл байтов и сохраняет получившееся прикладное состояние.") + p(
        "Поддерживаемая реализация находится в <code>RaftNet8/src/Raft</code> и работает только с <strong>net8.0</strong>. Имя сборки — <code>Raft.Net8</code>, пространство имён — <code>Raft</code>. Версия DBreeze закреплена: <code>1.142.2026.1016-beta</code>. Суффикс beta является частью опубликованной версии зависимости. Старые проекты Framework/Standard и <code>legacy-source/</code> сохранены как исторические материалы с другими контрактами.") + p(
        "Мы построим небольшое реплицируемое хранилище ключей и значений. Три процесса будут держать независимые дисковые копии. Успешный <code>put</code> означает, что кворум голосующих узлов сохранил команду, а лидер применил её к приложению. Затем мы перезапустим процесс, создадим снимок и повторим опыт с полностью энергозависимым хранением в RAM.") + callout(
        "Публичный API для клиентов создаёт ваше приложение", "Ядро не открывает публичный сервисный endpoint. Дополнительные библиотеки Raft.Cluster.Server и Raft.Cluster.Client теперь предоставляют именованные потоки, HTTP(S), обнаружение лидера и повторы: см. следующие главы о клиентах. Остальные главы также обучают низкоуровневому embedded API. Политику доступа задаёт хост.") + h("Как читать книгу") + ol(
        "Запустите существующую демонстрацию, если хотите сразу увидеть выборы и репликацию.",
        "Соберите соседний проект <code>examples/TutorialNode</code> и откройте три терминала.",
        "Перед изменением примеров разберитесь в контракте приложения, записи и чтения.",
        "Перед работой с постоянными данными прочитайте главы о диске, памяти, лимитах и восстановлении.") + p(
        "Если не указано иное, все команды выполняются из каталога репозитория <code>RaftNet8/</code>. У обеих языковых версий одинаковые адреса глав: переключение языка сохраняет выбранную главу. Для чтения этой HTML-книги не нужны сервер, интернет и установка зависимостей. Соседний проект C# нужен только для запуска примеров."))

    add("consensus", "Кластер, журнал и кворум", p(
        "<strong>Голосующий узел</strong>, или voter, участвует в выборах и подтверждении истории. <strong>Ученик</strong>, или learner, получает журнал, исключён из подсчёта кворума и не начинает выборы. <strong>Лидер</strong> координирует репликацию; последователи получают его записи. Term — эпоха выборов, index — положение записи в журнале. Committed означает, что запись стала частью согласованной истории. Applied означает, что локальное приложение уже выполнило эту запись.") + table(
        ["Голосующих", "Кворум", "Допустимо недоступных", "Практический смысл"], [
            ["1", "1", "0", "Удобно для обучения; отказоустойчивости между репликами нет."],
            ["2", "2", "0", "Две копии, но для продолжения работы нужны обе."],
            ["3", "2", "1", "Обычный небольшой кластер."],
            ["5", "3", "2", "Выше устойчивость к отказам и больше работы по репликации."]]) + p(
        "Для фиксированного активного состава кворум равен <code>voterCount / 2 + 1</code> при целочисленном делении. Сам узел учитывается только тогда, когда он голосующий. Ученики и просто перечисленные в <code>KnownPeers</code> адресаты кворум не увеличивают и не заменяют. При изменении состава активная конфигурация определяется последней записью конфигурации в журнале, в том числе ещё не подтверждённой. Старый файл запуска не является источником текущего кворума.") + quorum_lab(True) + p(
        "Если в группе из трёх голосующих недоступны двое, безопасная запись и свежее чтение с подтверждением кворума останавливаются. Оставшийся процесс может показывать старое значение. Название Leader в устаревшем представлении не создаёт большинство. Дополнительные реплики повышают устойчивость к отказам, но не делят поток записей одной группы на независимые шарды.") + flow(True) + p(
        "Реализация сохраняет term/vote до зависимого ответа, а записи журнала — до подтверждения репликации. После избрания лидер добавляет no-op; правило подтверждения записей своего term защищает предыдущую историю. Через API узла вы используете эти гарантии, но повторное выполнение прикладных эффектов всё равно должно быть безопасным."))

    add("setup", "Подготовка .NET 8 и сборка", p(
        "Установите SDK .NET 8. Файл <code>global.json</code> выбирает семейство 8.0.400 с переходом на последний доступный feature band внутри .NET 8. Поэтому <code>dotnet --version</code> из каталога <code>RaftNet8/</code> должен показывать 8.0.x даже при установленном более новом SDK. Исходники используют C# 12, nullable-типы и предупреждения как ошибки.") + code(
        "dotnet --version\ndotnet restore Raft.Net8.sln --locked-mode\ndotnet build Raft.Net8.sln -c Release --no-restore\ndotnet test tests/Raft.Tests -c Release --no-build --no-restore", "shell") + p(
        "Соседний учебный проект намеренно не включён в основное решение. Соберите его один раз до открытия нескольких терминалов: тогда процессы не будут одновременно пересобирать один каталог результатов.") + code(
        "dotnet restore docs/human/tutorial/examples/TutorialNode/TutorialNode.csproj --locked-mode\ndotnet build docs/human/tutorial/examples/TutorialNode/TutorialNode.csproj -c Release --no-restore", "shell") + h("Подключение проекта библиотеки") + code(
        (EXAMPLES / "TutorialNode.csproj").read_text(encoding="utf-8"), "xml", "TutorialNode.csproj") + p(
        "Этот относительный путь правильный именно для соседнего учебного проекта. В своём приложении скорректируйте путь к <code>src/Raft/Raft.csproj</code> и задайте <code>net8.0</code>. Централизованные версии зависимостей и lock-файлы обеспечивают нужную версию DBreeze. Номер сборки в исходниках сам по себе не означает, что соответствующий пакет уже опубликован в NuGet.") + callout(
        "Версия зависимости и формат данных — разные вопросы", "Восстановление более нового пакета базы не мигрирует журнал Raft, схему приложения или сетевой протокол. В примерах используется закреплённая в репозитории зависимость и явно выбранный формат v3."))

    add("demo", "Наблюдение за готовой демонстрацией", p(
        "Самый быстрый опыт — существующее решение HumanTest. Его три узла работают в одном процессе, но общаются по настоящему TCP через loopback и используют разные дисковые базы и каталоги снимков.") + code(
        "dotnet run --project HumanTest/Raft.Demo -c Release --no-build", "shell") + code(
        "status\nset greeting hello from Raft\nget greeting\nload 1000\nsnapshot\nstatus", "text", "Введите в консоли демонстрации") + p(
        "Сначала посмотрите <code>status</code> и определите фактического лидера, затем изолируйте именно его. Указанный ниже n1 — пример, а не обещанный победитель выборов.") + code(
        "isolate n1\nstatus\nheal\nstop n2\nstart n2\nadd n4\npromote n4\ntransfer n4\nremove n1\nstatus\nexit", "text") + p(
        "Демонстрация сама направляет <code>set</code>/<code>get</code> известному лидеру; в вашем сервисе такую маршрутизацию нужно реализовать. Команда <code>get</code> выполняет ReadIndex перед запросом к приложению. Во время выборов или изменения состава административная команда может сообщить о незавершённом переходе. Дождитесь стабильного состояния и повторяйте операции по одной.") + code(
        "dotnet run --project HumanTest/Raft.Demo -c Release --no-build -- --scenario", "shell") + p(
        "Автоматический сценарий завершается сообщением <code>SCENARIO PASS</code>. Интерактивный запуск повторно использует <code>.data/human-test-v4/</code>; сценарии обычно создают новый каталог в <code>.data/scenarios/</code>. Параметр <code>--data &lt;новый-каталог&gt;</code> позволяет начать новый опыт, не удаляя предыдущие базы. У учебного приложения из следующей главы другие команды и каталоги.") + p(
        source_link("HumanTest/README.md", "Полная инструкция демонстрации") + " · " + source_link("HumanTest/Raft.HumanTest.sln", "Решение для ручного запуска")))

    add("cluster-lab", "Запуск трёх отдельных процессов C#", p(
        "После сборки учебного проекта откройте три терминала в одном каталоге <code>RaftNet8/</code>. В каждом выполните только свою строку. По умолчанию используются адреса <code>127.0.0.1:6300</code>, <code>:6301</code> и <code>:6302</code>. Порядок узлов, имя группы и список голосующих одинаковы во всех процессах.") + code(
        "# Терминал 1\ndotnet run --project docs/human/tutorial/examples/TutorialNode -c Release --no-build -- n1\n\n# Терминал 2\ndotnet run --project docs/human/tutorial/examples/TutorialNode -c Release --no-build -- n2\n\n# Терминал 3\ndotnet run --project docs/human/tutorial/examples/TutorialNode -c Release --no-build -- n3", "shell") + p(
        "Каждый процесс печатает <code>STARTED</code> после запуска локального runtime и listener. Это ещё не готовность кворума. Вводите <code>status</code>, пока один процесс не покажет <code>role=Leader</code>. В примере таймер выборов равен 1–2 секундам, чтобы дисковый опыт имел больший запас, чем настройки библиотеки по умолчанию. Следующие команды отправляйте в терминал лидера:") + code(
        "status\nput request-001 greeting привет от трёх процессов\nget greeting\nput request-001 greeting привет от трёх процессов\nlocal greeting\nsnapshot", "text") + p(
        "Повтор одинакового запроса создаёт ещё одну запись журнала, но сохраняет первый прикладной результат и его <code>originalIndex</code>. Команда <code>get</code> подтверждает свежесть через кворум; <code>local</code> прямо допускает устаревший результат. Если повторно использовать <code>request-001</code> с другим ключом или значением, приложение напечатает <code>CONFLICT</code> и сохранит первый результат. В соседнем проекте явно выбран UTF-8 для stdin/stdout, включая перенаправление Windows: ключи и значения поддерживают кириллицу.") + ol(
        "Остановите лидера командой <code>quit</code>. Дождитесь нового лидера среди двух оставшихся голосующих и запишите там <code>request-002</code>.",
        "Снова запустите остановленный процесс той же командой и с тем же каталогом. Посмотрите догоняющую репликацию через <code>status</code> и <code>local greeting</code>.",
        "Остановите два процесса из трёх. Оставшийся узел не сможет безопасно подтвердить запись и ReadIndex. Верните кворум, не удаляя базы.",
        "Завершите все процессы, затем запустите те же три команды и прочитайте данные через нового лидера. Дисковые значения и записи дедупликации должны сохраниться.") + callout(
        "Сохраняйте идентичность учебного кластера", "Корень по умолчанию: <code>.data/tutorial/&lt;узел&gt;/</code>. Для новой группы задайте всем процессам новый общий корень <code>--data</code>. Если порты 6300–6302 заняты, укажите одинаковый <code>--base-port</code> во всех терминалах. Не запускайте одновременно две копии одной идентичности/каталога. Не передавайте этому примеру базы существующей HumanTest-демонстрации.", "warn") + p(
        "Для опыта в одном процессе добавьте к n1 параметры <code>--single --data .data/tutorial-single</code>. Единственный голосующий не даёт отказоустойчивости между репликами. Для разных машин замените loopback-адреса на доступные сетевые адреса: текущая CLI намеренно предназначена для локального обучения."))

    add("bootstrap", "Настройка и восстановление узла", excerpt("TutorialSettings.cs", "options") + p(
        "Это <strong>переопределения учебного примера</strong>, а не значения библиотеки по умолчанию. Heartbeat составляет 50 мс, выборы назначаются в диапазоне <code>[40,80)</code> тактов по 25 мс — 1–2 секунды; дедлайн RPC равен 500 мс. <code>Members</code> содержит n1/n2/n3 либо только n1 для отдельного одиночного опыта. Идентификатор формата приложения и снимков — <code>book-kv-v1</code>.") + table(
        ["Входные данные", "Как выбирать", "Чего они не делают"], [
            ["<code>NodeId</code>", "Стабильное уникальное имя реплики.", "Изменение параметра не переименовывает существующую базу."],
            ["<code>GroupId</code>", "Одна логическая группа на всех её узлах.", "Это не пароль и не средство аутентификации."],
            ["<code>Members</code> / <code>Learners</code>", "Общий начальный состав новой группы.", "Параметры не переписывают восстановленный состав."],
            ["<code>KnownPeers</code>", "Bootstrap-ID для совместимости; wire3 использует InitialPeers и журналируемый справочник.", "Перечисление не даёт права голоса."],
            ["PeerDescriptor / InitialPeers", "Общие начальные маршруты и локальный listen endpoint; новые маршруты реплицируются.", "Изменение маршрута не меняет состав голосующих."],
            ["Каталоги", "Разные постоянные корни журнала, приложения и снимков для каждого узла.", "Новый пустой путь не заменяет безопасно утраченную подтверждённую историю."]]) + excerpt("Program.cs", "startup") + p(
        "<code>CreateAsync</code> проверяет восстановленный журнал и checkpoint приложения, завершает восстановление незаконченной установки снимка и готовит runtime. <code>StartAsync</code> запускает участие в протоколе. <code>tcp.Start(node.HandleAsync)</code> подключает входящие RPC. После запуска приложению может ещё потребоваться применение подтверждённой истории; успешный ReadIndex на лидере служит барьером готовности к чтению.") + callout(
        "Для новых данных выбирайте v4/wire3 явно", "<code>DBreezeLogLayout.UnifiedTableV4</code> передаётся отдельным аргументом конструктора. Конструкторы без него сохраняют выбор v2 с отдельными таблицами ради совместимости. Wire3 требует v4. Открытие v2/v3 как v4 отклоняется; конвертера в v4 сейчас нет."))

    add("application", "Детерминированная прикладная модель", p(
        "Raft реплицирует байты команд, а не произвольные изменения, выполненные напрямую в вашей базе. Создавайте ID запроса, время и другие внешние решения до отправки, включайте их в команду и одинаково интерпретируйте на всех репликах. Поле версии позволяет явно обнаруживать неподдерживаемые команды вместо незаметного изменения смысла старой истории.") + excerpt("BookState.cs", "encode") + p(
        "Входной шлюз проверяет бизнес-поля и размер закодированных байтов до вызова <code>ProposeAsync</code>. Библиотека дополнительно проверяет свой размерный лимит, но не знает вашей JSON-схемы. Если недопустимая команда обнаружена только при применении, она уже попала в согласованную историю. Пример останавливается при такой ошибке выполнения, а не выдаёт её за обычную ошибку входных данных.") + excerpt("BookState.cs", "apply") + p(
        "Приложение сохраняет значения по ключам <code>1.ToIndex(key)</code>, а первые результаты запросов — по <code>2.ToIndex(requestId)</code> в одной физической бизнес-таблице <code>book/data</code>. Вспомогательный класс использует отдельную таблицу <code>book/checkpoint</code> для проверяемой пары <code>(index, term)</code>. Обе таблицы изменяются одной короткой транзакцией DBreeze. Класс резервирует их до зависимых чтений, делает один Commit и лишь затем публикует применённый индекс.") + p(
        "Внутри обработчика нельзя вызывать <code>Commit</code>, открывать транзакцию на захваченном живом engine, выполнять await, обращаться к внешним сервисам, часам или случайным данным, изменять живой кэш. При построении снимка этот обработчик выполняется повторно в отдельном поколении базы. Запись в бизнес-таблицу в обход применения подтверждённой команды нарушает репликацию и равенство состояний.") + excerpt("BookState.cs", "disk-state") + p(
        "Готовые классы автоматически пропускают бизнес-эффекты no-op и записей конфигурации, но продвигают через них checkpoint. В собственной реализации <code>IStateMachine</code> проверяйте <code>entry.IsNoOp</code> и всё равно обновляйте <code>LastApplied</code>. Постоянное приложение должно реализовать <code>ICheckpointStateMachine</code> и сообщать пару индекс/term, соответствующую реальным дисковым эффектам. <code>IBatchStateMachine</code> объединяет применение в транзакции, сохраняя порядок журнала.") + callout(
        "Обычный бизнес-отказ — это результат", "Недостаточный баланс, занятый ID и другой допустимый бизнес-отказ оформляйте как детерминированный сохранённый результат с продвижением checkpoint. Исключение из Apply — сигнал остановки узла, а не способ вернуть обычную бизнес-ошибку. Пример сохраняет первый результат ID и обнаруживает конфликт после применения.", "warn"))

    add("writes", "Запись, повторы и смысл ответа", excerpt("Program.cs", "propose") + p(
        "<code>ProposalResult</code> содержит <code>Index</code> и <code>Term</code> новой подтверждённой записи. Это не результат бизнес-операции. После успеха пример читает свою постоянную строку результата запроса и различает первое выполнение, повтор и конфликт использования ID. В общем сервисе сохраняйте бизнес-результат и отдавайте его по ID через безопасное чтение лидера.") + table(
        ["Исход", "Что он означает", "Действие вызывающего"], [
            ["Успех", "Кворум голосующих сохранил запись, лидер применил её локально.", "Используйте результат; последователи могут ещё отставать."],
            ["<code>NotLeaderException</code>", "Этот узел не принимает операцию лидера; LeaderId может быть null.", "Обновите маршрут и отправьте тот же ID и замысел операции."],
            ["Отмена / таймаут клиента", "Ожидание прекращено; команда могла подтвердиться или примениться позже.", "Запросите/повторите результат с тем же ID и содержимым."],
            ["<code>UncommittedLogLimitException</code>", "Исчерпан бюджет неподтверждённых байтов.", "Ограничьте производителей и повторяйте с задержкой после прогресса кворума."],
            ["Ошибка хранилища/приложения", "Участие останавливается; результат сохранения может быть неопределённым.", "Наблюдайте Completion, остановите/освободите узел, сохраните файлы и восстановитесь."]]) + p(
        "Встроенной дедупликации клиентов в библиотеке нет. В примере строка первого результата, бизнес-эффект и checkpoint сохраняются одной транзакцией. Поэтому повтор не повторяет первый бизнес-эффект, даже если ответ потерялся. Однако повторы всё ещё создают записи журнала и работу приложения: это не оптимизация транспорта.") + p(
        "ID запроса должен оставаться тем же при повторах и соответствовать одному содержимому. Новый ID создаётся для новой логической операции. Учебное приложение хранит результаты запросов бессрочно, поэтому база растёт даже при постоянном числе ключей. Для рабочей системы нужны ограниченные сессии/срок хранения и понятный горизонт повторов. Удаление старого результата при ещё допустимом повторе позволяет повторный эффект.") + callout(
        "Внешним эффектам нужен отдельный протокол", "Подтверждённый callback не делает письмо, платёж или HTTP-вызов exactly-once. Сохраните outbox вместе с бизнес-эффектом, затем доставляйте его отдельным worker с идемпотентным получателем. Повтор приложения при построении снимка не должен повторно отправлять внешние действия.", "warn") + p(
        "Не меняйте входные байты и не возвращайте арендованный буфер в пул, пока <code>ProposeAsync</code> ещё использует его. Узел создаёт собственную копию после admission; простое безопасное правило — сохранять входную память неизменной до завершения вызова. Отмена запроса не изымает команду из постоянного журнала."))

    add("reads", "Как безопасно прочитать актуальные данные", excerpt("Program.cs", "read") + p(
        "ReadIndex — барьер, а не готовый снимок базы. Лидер подтверждает свежий контекст кворумом, требует подтверждения записи текущего term, фиксирует committed index и ждёт локального применения как минимум до него. После этого читайте <strong>потокобезопасное приложение того же лидера</strong>. Результат может включать и более поздние уже применённые записи — это допустимо для актуального чтения.") + p(
        "Нельзя получить ReadIndex на n1, а затем прочитать локальную базу n2. Нельзя кэшировать барьер для произвольных будущих запросов. Проверка <code>Status.Role == Leader</code>, недавний heartbeat и равенство <code>LastApplied == CommitIndex</code> не являются свежим подтверждением кворума. При сетевом разрыве бывший лидер может продолжать показывать старое локальное значение.") + table(
        ["API", "Назначение", "Цена и граница"], [
            ["<code>ReadIndexAsync</code>", "Барьер свежего чтения лидера без новой записи журнала.", "Нужны кворум и локальное применение; wire2/3."],
            ["<code>ReadBarrierAsync</code>", "Совместимый барьер через подтверждённый no-op.", "Создаёт дисковую запись; работает для wire1."],
            ["Get приложения / local", "Чтение текущего применённого состояния этого узла.", "Может устареть; используйте только с явным таким контрактом."],
            ["<code>Status</code>", "Опубликованные диагностические сведения.", "Не даёт гарантии согласованности чтения данных."]]) + p(
        "Метод <code>Read</code> приложения с поколениями защищает активный engine во время переключения поколений. Возвращайте из callback материализованное значение или DTO, но не ленивую строку DBreeze, перечислитель, nested handle или ссылку на engine. ReadIndex не превращает произвольное чтение нескольких таблиц в транзакционный снимок: согласованность сложного запроса организует приложение.") + p(
        "Lease-чтений и автоматической переадресации с последователя на лидера нет. Публичный endpoint и поведение при смене лидера определяет ваш хост. API устаревающего чтения тоже может быть полезен, но его договорённость должна быть явно видна пользователю."))

    add("disk", "Какие именно данные лежат на диске", path_tree(True) + p(
        "Каждый узел хранит собственную копию. Корень примера — <code>.data/tutorial-v4/n1</code>, аналогично для n2/n3. Один engine DBreeze обслуживает журнал Raft, другой — активное поколение приложения. Дерево выше логическое: DBreeze сам назначает номера физических файлов, хранит схему, журнал транзакций и rollback/helper-файлы. Имя таблицы не обязано совпадать с именем файла.") + table(
        ["Слой", "Постоянные сведения", "Зачем нужны"], [
            ["Идентичность Raft", "Имена узла/группы, начальный контекст и известные участники.", "Защита от случайного открытия каталога другой репликой или группой."],
            ["Hard state/frontier", "Текущий term, отданный голос, committed frontier и проверяемые границы/хвост журнала.", "После рестарта нельзя повторно проголосовать в одном term или выдумать другую постоянную историю."],
            ["Журнал", "Index, term, вид записи и байты команды/конфигурации, включая неподтверждённый суффикс.", "Репликация, исправление конфликтов, восстановление и replay приложения."],
            ["Индекс конфигураций", "Сохранённые изменения состава и восстанавливаемая история конфигурации.", "Восстановление и откат используют журнал, а не отредактированный список запуска."],
            ["Метаданные/intent снимка", "Включённые index/term, состав, ID/digest образа; незавершённый install intent при наличии.", "Связь удалённого префикса с образом и завершение прерванной установки."],
            ["Поколение приложения", "Значения, первые результаты запросов и checkpoint index/term с CRC.", "Перезапуск без потери прикладных эффектов и защита от повторов."],
            ["Репозиторий образов", "Опубликованные архивы/дескрипторы, частичные входящие файлы/прогресс и временные сборки.", "Догоняющая репликация после compaction, продолжение передачи, локальное восстановление."]]) + h("V4: одна основная таблица, а не один файл") + p(
        "Таблица <code>raft8/v4</code> хранит изменяемое состояние консенсуса в упорядоченных пространствах ключей: <code>1.ToIndex(metadataKey)</code>, <code>2.ToIndex(logIndex)</code>, <code>3.ToIndex(configurationIndex)</code>, а также 4 для служебного индекса и 5 для результатов. Hard state и постоянные границы объединены проверяемым RF4M manifest. В старых таблицах метаданных также сохраняются небольшие защитные записи, чтобы несовместимый reader отказался от открытия. Системные и rollback-файлы DBreeze остаются. Слово unified не означает, что для резервной копии достаточно одного файла таблицы.") + p(
        "V2 использует <code>raft8/v2/meta</code>, <code>raft8/v2/log</code> и <code>raft8/v2/config</code>. У записей v2/v3 есть проверки целостности; это обнаружение повреждения, а не шифрование и не защита от злонамеренного участника. Учётные 21 байт на запись относятся к бюджетам памяти/передачи. Проверяемая дисковая запись добавляет 37 байт до собственных расходов DBreeze на ключи, индексы и транзакционный журнал. Нельзя оценивать объём диска только по полезным данным.") + h("Что не сохраняется постоянно") + p(
        "Открытые сокеты, ожидающие задачи клиентов, контексты чтения, текущая роль лидера, незавершённые RPC и ограниченный кэш журнала — состояние runtime. Кэш ускоряет доступ к постоянным записям. Его лимит 8 МиБ по умолчанию не равен размеру базы и не выбирает режим долговечности. После рестарта runtime восстанавливает участие и догоняет историю по постоянным данным.") + callout(
        "Без снимков нет автоматического ограничения журнала", "При SnapshotIntervalEntries=0 и без ручных снимков журнал продолжает расти. Снимки позволяют удалять старые записи журнала, но бизнес-данные и строки дедупликации остаются внутри состояния приложения и образа. Хранение снимков не является политикой удаления прикладных данных.", "warn"))

    add("memory", "Режим в памяти и его реальные ограничения", p(
        "В современной реализации есть фабрика журнала в памяти. Она запускает DBreeze с <code>Storage = MEMORY</code>. Для полностью энергозависимого опыта пример также использует отдельный memory-engine для бизнес-эффектов и checkpoint и оставляет <code>SnapshotDirectory</code> равным null.") + code(
        "var storage = DBreezeLogStorage.CreateInMemory(\n    options, DBreezeLogLayout.UnifiedTableV4);\nawait using var log = new RaftStorageAdapter(storage);", title="Фабрика журнала в памяти") + excerpt("BookState.cs", "memory-state") + code(
        "dotnet run --project docs/human/tutorial/examples/TutorialNode -c Release --no-build -- n1 --single --memory", "shell") + p(
        "Дождитесь Leader, запишите значение и завершите процесс. Запустите ту же команду ещё раз и прочитайте после новых выборов: значение и сохранённые результаты запросов исчезли. Этот режим не сохраняет данные Raft и приложения в каталог базы; TCP всё ещё использует сокеты, CLR выделяет память, а ОС может выгружать страницы процесса. Это не обещание, что байты никогда не попадут в swap или диагностический дамп машины.") + table(
        ["Сочетание", "Поведение при рестарте", "Назначение"], [
            ["Дисковый журнал + дисковое приложение с поколениями + образы", "Восстанавливается проверяемое состояние журнала/приложения, при необходимости устанавливаются и проигрываются снимки.", "Постоянный путь этой книги."],
            ["Журнал и приложение в RAM, без образов", "Теряются term, vote, журнал, значения, ID запросов и checkpoint.", "Одноразовые опыты и тесты."],
            ["Дисковый журнал + новое volatile-приложение", "Replay возможен, только если сохранён весь нужный префикс либо его восстановит совместимое snapshot-приложение.", "Специально спроектированная интеграция; это не режим данной CLI."],
            ["Журнал в RAM + постоянное приложение", "Приложение может оказаться впереди забытых committed-данных; стартовые проверки могут отказать.", "Не является постоянной конфигурацией Raft."]]) + callout(
        "Голосующие в RAM не дают гарантий crash-recovery", "Если узел забывает term, vote и журнал, а затем возвращается под прежней голосующей идентичностью, нарушаются предпосылки стабильного хранения Raft и может нарушиться безопасность. Нельзя перезапускать потерявший память voter в живой рабочий кластер как прежнюю реплику. Используйте дисковых голосующих и поддерживаемую процедуру замены состава. Каждый запуск полностью RAM-опыта считайте новой одноразовой группой.", "warn") + p(
        "Изменение <code>LogCacheBytes</code> не переводит хранилище в RAM. Встроенная реализация поколений и снимков использует диск. Memory-режим соседнего проекта намеренно не поддерживает снимки. При этом прикладная RAM-база продолжает расти с новыми значениями и ID запросов до завершения процесса."))

    add("snapshots", "Снимки, compaction и догоняющая репликация", p(
        "Снимок представляет прикладное состояние до подтверждённой и применённой пары <code>(index, term)</code> и конфигурацию на этой границе. После надёжной публикации полного образа старый префикс журнала можно удалить. Сильно отставший последователь получает образ и продолжает с более поздних записей вместо запроса всех уже удалённых команд.") + code(
        "using var deadline = new CancellationTokenSource(TimeSpan.FromMinutes(2));\nvar metadata = await node.CreateSnapshotAsync(deadline.Token);\nConsole.WriteLine($\"Image includes {metadata.LastIncludedIndex}/{metadata.LastIncludedTerm}\");", title="После запуска и применения хотя бы одной записи") + p(
        "Нужны абсолютный эксклюзивный <code>SnapshotDirectory</code> и реализация <code>ISnapshotStateMachine</code>. Класс <code>DBreezeGenerationStateMachine</code> предоставляет её для отдельного абсолютного корня приложения. Положительный <code>SnapshotIntervalEntries</code> включает автоматическое построение; ноль оставляет только ручное. В учебном примере снимки ручные, чтобы жизненный цикл данных был виден.") + ol(
        "Построение закрепляет committed/applied-границу и повторяет детерминированный обработчик в независимом поколении, при наличии начиная с предыдущего образа.",
        "Поколение закрывается и архивируется. Для образа вычисляется SHA-256; метаданные и дескрипторы проверяются.",
        "Постоянный образ публикуется, а compaction сохраняет настроенный хвост журнала.",
        "Передача идёт ограниченными блоками с CRC, постоянным прогрессом приёма и возобновляемыми offset. Intent установки и атомарный указатель поколения позволяют завершить переход после рестарта.") + p(
        "Такой путь не предполагает наличия у DBreeze общего MVCC-снимка базы. Цена — CPU для replay, дополнительные транзакции, работа с архивами и временное место. Планируйте одновременное размещение живого приложения, replay/build или подготовленного поколения, архивов и оставшегося журнала. <code>MaxSnapshotBytes</code> и <code>MaxSnapshotUnpackedBytes</code> ограничивают отдельный архив/распаковку, но не весь объём каталогов.") + p(
        "Отмена прекращает ожидание вызывающего, но не обязательно уже начатое построение. Во время retention, приёма или другой сборки ручной вызов может сообщить busy. Текущий, передаваемый или подготовленный образ может быть закреплён сверх обычного числа хранимых снимков. Не удаляйте закреплённые файлы, не редактируйте указатели поколений и не обрезайте журнал вручную.") + callout(
        "Снимок не является кнопкой сброса аварийного кластера", "Один образ не является поддерживаемым API force-new-cluster. Сохраняйте согласованную резервную копию журнала, поколения приложения и репозитория снимков с прежними идентичностями и форматом приложения. Сокращённый журнал не восстановит новое приложение без совместимого образа.", "warn"))

    add("membership", "Hot Add/Remove без рестарта реплик", membership_chapter("ru"))

    add("membership-state", "Хранение, доверие и пределы изменения состава", membership_state_chapter("ru"))

    add("transfer", "Передача лидерства перед обслуживанием", code(
        "await oldLeader.TransferLeadershipAsync(\"n2\", token);\n// Переключите клиентский маршрут на n2, затем проверьте готовность:\nawait newLeader.ReadIndexAsync(token);", title="oldLeader/newLeader — локальные объекты соответствующих хостов") + p(
        "Целью передачи должен быть допустимый голосующий. Текущий лидер прекращает принимать новые предложения, чтения и изменения состава, догоняет цель, отправляет TimeoutNow и ждёт, пока увидит её новым лидером. Успех означает такое наблюдение; незавершённая передача прерывается механизмом election timeout. Произвольный ученик не может стать целью до повышения.") + p(
        "Считайте <code>LeadershipTransferInProgressException</code> временным состоянием маршрутизации. Отмена ожидания не отзывает уже отправленную передачу. Успех не означает, что ваш публичный балансировщик уже переключился: обновите клиентский маршрут и выполните свежий ReadIndex на новом лидере до остановки старого хоста.") + p(
        "При плановом последовательном обслуживании сначала передайте лидерство с останавливаемого узла, сохраняйте работающий кворум, после рестарта проверьте догоняющую репликацию и лишь затем обслуживайте следующего voter. Библиотека не составляет глобальное расписание обслуживания и не переносит ресурсы вашего приложения."))

    add("lifecycle", "Владение ресурсами, остановка и fail-stop", table(
        ["Ресурс", "Владелец", "Действие при остановке"], [
            ["RaftNode", "Ваш хост", "DisposeAsync и наблюдение за Completion."],
            ["ILogStore после успешного CreateAsync", "Узел", "Узел закрывает store; нужна защита на случай ошибки создания."],
            ["Обёрнутый IRaftStorage", "RaftStorageAdapter", "Адаптер закрывает хранилище и worker."],
            ["Engine, созданный конструктором с путём", "Хранилище", "Закрывается своим хранилищем."],
            ["Переданный снаружи engine", "Вызывающий, если владение явно не передано", "Освобождается после остановки узла/приложения."],
            ["Транспорт, state machine, сертификат, logger factory", "Вызывающий", "Узел не принимает владение ими."]]) + excerpt("Program.cs", "shutdown") + p(
        "Сначала остановите входящий транспорт, затем узел/store, после этого — принадлежащее вызывающему приложение и engine. Области жизни примера соблюдают порядок и при обычном выходе, и при ошибках. Store защищён даже при неуспешном создании узла; повторное освобождение адаптера безопасно. Закрытие engine до завершения прикладного/storage-worker приводит к ошибкам.") + p(
        "Обязательно наблюдайте <code>node.Completion</code>. Задача завершается при остановке и получает исходное исключение при ошибке выполнения хранения/приложения. Цикл учебной консоли ждёт одновременно ввода и Completion, поэтому поломанный узел не остаётся незаметно работать, пока пользователь ничего не вводит.") + code(
        "var finished = await Task.WhenAny(hostStopping, node.Completion);\nif (finished == node.Completion)\n    await node.Completion; // Исходная ошибка передаётся супервизору.", title="Шаблон сервиса; hostStopping предоставляет ваш хост") + callout(
        "Нельзя продолжать после неопределённого сохранения", "После ошибки storage или приложения остановите участие, сохраните файлы, освободите ресурсы и создайте новый экземпляр через восстановление. Повтор неопределённой мутации на неисправном экземпляре нарушает договорённость о постоянном состоянии. Тип исключения не превращает ошибку выполнения в недопустимый ввод.", "warn"))

    add("limits", "Размеры буферов и значимые константы", p(
        "Здесь приведены текущие значения <code>RaftOptions</code> по умолчанию, а не учебные переопределения таймеров. КиБ — 1024 байта, МиБ — 1 048 576 байт. Пределы проверяются при создании; они также должны быть совместимы с сохранёнными командами и декодерами всех участников.") + table(
        ["Параметр", "По умолчанию", "Допустимый предел и смысл"], [
            ["MaxCommandBytes", "65 536 Б (64 КиБ)", "1..16 МиБ. Вся закодированная команда, включая поля и JSON-метаданные."],
            ["MaxAppendEntries", "128", "1..4096 записей; общий счётный предел для proposal, replication и application batching."],
            ["MaxAppendBytes", "262 144 Б (256 КиБ)", "Не меньше MaxCommandBytes + 21, не больше 64 МиБ. Бюджет применения/replay и старого wire1."],
            ["MaxProposalBatchBytes", "null → 1 051 264 Б", "Отдельная локальная группа постоянной записи; минимум команда + 21, максимум 64 МиБ и MaxUncommittedBytes."],
            ["MaxReplicationBytes", "null → 1 051 264 Б", "Бюджет записей пакета wire2/3; явное значение должно помещаться в MaxInFlightBytes − 64 и 64 МиБ."],
            ["MaxPendingProposals / MaxPendingReads", "1024 / 1024", "Каждый 1..1 000 000. Ограничивает принятые операции, но не все задачи снаружи, ожидающие admission."],
            ["MaxInFlightMessages", "4 на адресата", "1..256. Для pipeline нужен запас больше одного; в Probe может использоваться меньше."],
            ["MaxInFlightBytes", "4 МиБ на адресата", "Не меньше MaxAppendBytes + 64 и современного пакета + 64; максимум 1 ГиБ."],
            ["MaxUncommittedBytes", "64 МиБ", "Не меньше MaxAppendBytes; максимум 1 ТиБ. Бюджет постоянного неподтверждённого суффикса, а не всего журнала или RAM."],
            ["LogCacheEntries / LogCacheBytes", "1024 / 8 МиБ", "Действуют оба ограничения; нулевое число записей выключает кэш. Объекты и DBreeze добавляют свои расходы."],
            ["Известные ID участников", "Максимум 1024", "ID узла/группы/приложения: 1..128 ASCII-букв, цифр, дефисов и подчёркиваний; voters/learners не пересекаются."],
            ["EnablePipelining / CoalesceCommitNotifications", "true / true", "Ограниченные современные flights и отложенные пустые уведомления commit."]]) + h("Автоматические байтовые бюджеты") + code(
        "entryAccounting = commandBytes + 21\nlocalGroup = min(4 * MaxAppendBytes + 21 * MaxAppendEntries,\n                 MaxUncommittedBytes, 64 MiB)\nwire2or3Packet = min(4 * MaxAppendBytes + 21 * MaxAppendEntries,\n                  MaxInFlightBytes - 64, 64 MiB)\nmaxFrame = max(wirePacket, SnapshotChunkBytes + (wire3 ? 900000 : 280000)) + 1024", "text", "Текущие формулы; явные nullable-параметры заменяют первые два автоматических результата") + p(
        "С настройками по умолчанию предел пакета/локальной группы равен <strong>1 051 264 Б</strong> — 1 МиБ + 2688 Б. Предел тела кадра — <strong>1 052 288 Б</strong>; TCP-префикс длины добавляет ещё 4 байта. Для wire1 величина wirePacket в формуле означает MaxAppendBytes. 21 байт — учёт записи, 64 байта — отдельный запас на flight; дополнительные константы кадра имеют другое назначение. Кадр чуть больше 1 МиБ может арендовать bucket ArrayPool на 2 МиБ. Длина кадра не равна точному объёму managed heap.") + p(
        "Например, команда после кодирования размером 16 КиБ учитывается как 16 405 байт. Стандартный пакет применения вмещает 15 таких записей, а локальная группа или пакет wire2/3 — 64 с учётом счётного предела. Для полных закодированных команд по 64 КиБ эти бюджеты вмещают соответственно 3 и 16 записей. Размер JSON включает метаданные и экранирование: значение на 16 КиБ не обязательно превращается в команду на 16 КиБ.") + h("Ограничения транспорта и worker") + table(
        ["Внутренний предел", "Текущее правило", "Пример с тремя настроенными адресами"], [
            ["Входящие TCP-соединения", "max(4, endpointCount × 2)", "6 одновременно принятых соединений."],
            ["Декодированные обработчики на соединение", "Wire2: max(1, min(MaxInFlightMessages + 4, MaxInFlightBytes / MaxFrameBytes))", "Целочисленное деление даёт 3, а не 4 или 8."],
            ["Исходящие exchanges", "Wire2: MaxInFlightMessages + 4; wire1: 1", "8 exchanges; у репликации дополнительно собственный предел 4 flights."],
            ["Очередь storage-адаптера", "2 операции плюс исполняемая", "Один отдельный синхронный storage-worker на адаптер."],
            ["Применение", "Один упорядоченный application-worker на запущенный узел", "Медленное приложение задерживает ответ клиенту."],
            ["Дедлайн чтения входящего кадра", "30 секунд", "Внутренняя константа транспорта, не RpcTimeout."]]) + memory_lab(True) + p(
        "Эти внутренние константы описывают данную версию; не все доступны как публичные настройки. Процесс дополнительно использует кэши DBreeze, сетевые/системные буферы, объекты CLR, бизнес-данные и очереди хоста. В RAM-режиме вся база находится вне лимита кэша журнала. Ограничивайте параллелизм публичных запросов, а не только admission внутри Raft.") + h("Связанные пределы увеличиваются вместе") + excerpt("IntegrationRecipes.cs", "larger-command") + p(
        "Это пример команды до 1 МиБ, а не обещание производительности. Бюджет применения остаётся не меньше команда+21, а пакет+64 помещается в окно адресата. Настройте совместимые размеры у всех получателей и учтите рост арендуемых буферов и постоянных команд. Уменьшение MaxCommandBytes ниже размера уже сохранённых команд может привести к отказу при восстановлении базы.") + h("Пределы снимков") + table(
        ["Параметр", "По умолчанию", "Контракт"], [
            ["SnapshotDirectory / SnapshotIntervalEntries", "null / 0", "Абсолютный эксклюзивный путь; ноль — только вручную. Для автоматического интервала нужен каталог."],
            ["SnapshotRetainEntries", "128", "0..1 000 000; хвост журнала, не число бизнес-записей."],
            ["SnapshotRetainedImages", "2", "2..64 последних образа плюс закреплённые."],
            ["SnapshotChunkBytes", "64 КиБ", "1 КиБ..4 МиБ; влияет и на максимальный кадр."],
            ["SnapshotBytesPerSecond", "16 МиБ/с", "Минимум 1 КиБ/с; общий исходящий snapshot-throttle узла."],
            ["MaxSnapshotBytes", "64 ГиБ", "Предел архива; не меньше одного блока."],
            ["MaxSnapshotUnpackedBytes", "128 ГиБ", "Предел распаковки; не меньше MaxSnapshotBytes."]]))

    add("timing", "Выборы, пакетирование и бюджеты ожидания", table(
        ["Параметр", "Значение библиотеки", "Соотношение"], [
            ["TickInterval", "25 мс", "1 мс..10 с; период логического такта."],
            ["HeartbeatTicks", "1", "Период heartbeat = ticks × TickInterval; минимум один такт."],
            ["ElectionMinTicks / ElectionMaxTicks", "12 / 24", "Случайное [min,max); по умолчанию от 300 до менее 600 мс; max ≤ 1 000 000 тактов."],
            ["RpcTimeout", "200 мс", "Положительный и меньше минимального election timeout; в пределах таймера runtime."],
            ["ProposalBatchDelay", "2 мс", "0..1 с и не больше половины периода heartbeat."],
            ["BulkProposalBatchDelay", "null → до 8 мс", "min(4 × малая задержка, один heartbeat, 1 с); явное значение также укладывается в heartbeat/1 с."],
            ["Сбор у одного voter", "Не больше 1 мс", "Намеренное окно накопления сокращается для единственного голосующего."]]) + p(
        "Проверка требует <code>ElectionMinTicks ≥ 10 × HeartbeatTicks</code> и <code>ElectionMaxTicks &gt; ElectionMinTicks</code>. Это минимальные соотношения, а не доказательство пригодности таймеров вашей среде. Учитывайте медленный дисковый Commit, сеть и TLS, планировщик CPU, паузы GC, работу приложения и очередь принятых запросов. Слишком маленькие значения вызывают постоянные выборы; чрезмерные увеличивают время обнаружения отказа.") + p(
        "Малое и bulk-окно собирают команды вне владельца консенсуса. Bulk применяется к группам, ограниченным байтами, когда другие уже принятые операции ждут кворума/применения; если все принятые операции уже стоят в очереди, окно сокращается. Заполненная по числу/байтам группа может уйти сразу. Дедлайн начинается с первой ожидающей команды и не продлевается каждым новым поступлением.") + p(
        "Чтобы убрать намеренное ожидание накопления, задайте одновременно <code>ProposalBatchDelay = TimeSpan.Zero</code> и <code>BulkProposalBatchDelay = TimeSpan.Zero</code>. Явная ненулевая bulk-задержка остаётся переопределением даже при нулевой малой. Измеряйте обмен между задержкой и числом транзакций: последовательный поток по одной команде не показывает поведение 64 параллельных вызывающих.") + callout(
        "Задержка уведомления commit — осознанный компромисс", "При современном wire2/3 и CoalesceCommitNotifications=true догнавший idle-последователь узнаёт новый commit index со следующим пакетом данных или плановым heartbeat. Его применение может отстать на этот логический heartbeat плюс I/O/сеть/очередь владельца. Кворумное сохранение и применение лидером всё равно предшествуют успеху клиента. Значение false возвращает немедленную попытку отправки, но существующий flight тоже может задерживать адресата. Для свежего чтения нужен ReadIndex лидера.") + p(
        "Дедлайн клиента независим от RpcTimeout и выборов. Он должен учитывать admission, постоянную репликацию и применение лидером, а не один сетевой обмен. Таймаут не доказывает отказ команды. 15 секунд ожидания в учебной консоли — настройка упражнения, не константа библиотеки."))

    add("performance", "Ограниченный параллелизм и полезная нагрузка", excerpt("IntegrationRecipes.cs", "load") + p(
        "Рецепт ограничивает одновременно исполняемые отправки числом 64. Производитель команд, тела входящих запросов и очереди публичного сервиса тоже должны быть ограничены. Миллионы задач в Task.WhenAll просто переносят неограниченную память за semaphore admission узла. Успешный вызов включает применение лидером, поэтому медленный детерминированный обработчик напрямую ограничивает полезную скорость.") + ol(
        "Держите один DBreeze engine на физический каталог и используйте короткие синхронные транзакции. Никакого await внутри транзакции.",
        "Перечисляйте все записываемые таблицы при создании helper. В своих read–modify–write транзакциях резервируйте полный write set до зависимых чтений.",
        "Применяйте упорядоченные составные ключи, префиксы и ограниченные диапазоны. Избегайте полного сканирования таблиц на горячем пути и в обслуживании.",
        "Разделяйте размер команды, пакет применения, локальную постоянную группу и сетевой пакет: изменение одного не изменяет автоматически остальные.",
        "Измеряйте нужное число голосующих, реальные размеры команд, постоянную работу приложения, диск и сеть. Фиксируйте p50/p99 и выделения памяти вместе с командами в секунду.") + p(
        "На каждый storage-адаптер приходится отдельный поток хранения, а на запущенный узел — поток приложения; дополнительно работают асинхронные сеть/таймеры и DBreeze. Поэтому много групп в одном процессе имеют цену по потокам и ресурсам. Чистый reducer консенсуса не выполняет I/O, но синхронный дисковый flush от этого не становится бесплатным.") + p(
        "Отчёт hot membership сравнивает wire3/v4 с предыдущим HEAD, включая полный Add под нагрузкой. Оценивайте скорость, p99 и выделения памяти отдельно: локальный диск/TCP не обещает ёмкость сети разных машин. Ранее выпущенный отчёт R18 с конкурентами относится к версии до hot membership и сохранён как историческое свидетельство.") + p(
        source_link("benchmarks/results/hot-membership-2026-11-14.html", "Hot membership: сравнение с HEAD") + " · " + source_link("benchmarks/results/winner-r18-2026-11-13.html", "Историческое сравнение R18") + " · " + source_link("benchmarks/README.md", "Методика и команды бенчмарков")))

    add("security", "Защита сети узлов и клиентского API", p(
        "Обычный TcpRaftTransport подходит для доверенной лабораторной сети. Имена группы и участника внутри RPC — маршрутизация, а не криптографическая аутентификация. В рабочем хосте ограничьте сеть и включите взаимный TLS с привязкой сертификата к идентичности Raft.") + excerpt("IntegrationRecipes.cs", "tls") + p(
        "Сертификат принадлежит вызывающему и должен содержать закрытый ключ. Показанная политика сохраняет системные проверки цепочки, имени и отзыва и дополнительно сверяет каждый ID с доверенным SHA-256-хэшем сертификата. Хэши доставляются доверенной конфигурацией, а не самим собеседником. TLS TargetHost по умолчанию равен ID участника Raft: SAN/имя сертификата должны подходить этому ID, а не только постороннему IP-адресу.") + p(
        "Для собственной PKI можно передать явный validation callback, но он обязан действительно проверять выбранную цепочку/политику имён. Безусловный true отключает защиту. Согласуйте ротацию, изменение доверия и доступность проверки отзыва на всей группе. TLS-handshake ограничен транспортным RpcTimeout, поэтому медленная валидация тоже влияет на доступность.") + p(
        "Peer mTLS не авторизует ваших бизнес-клиентов. В публичном HTTP/gRPC/сервисном слое нужны собственные права, rate/body limits, дедлайны и правила ID запросов. Команды и файлы базы могут содержать секретные данные. CRC и SHA-256 образов обнаруживают повреждения, но не обеспечивают конфиденциальность и не защищают от злонамеренной реплики.") + callout(
        "Модель отказов", "Это Raft для crash/recovery незлонамеренных, non-Byzantine узлов. Он не защищает от намеренно лгущего участника, произвольной ручной правки таблиц или накопителя, который подтверждает flush, не сохраняя необходимые данные.", "warn"))

    add("diagnostics", "Наблюдение за индексами, отставанием и ошибками", code(
        "var status = node.Status;\nConsole.WriteLine($\"{status.NodeId}: {status.Role}, term={status.Term}, \" +\n    $\"commit={status.CommitIndex}, applied={status.LastApplied}, tail={status.LastLogIndex}\");\nforeach (var peer in status.Peers)\n    Console.WriteLine($\"{peer.NodeId}: match={peer.MatchIndex}, \" +\n        $\"next={peer.NextIndex}, flights={peer.InFlightMessages}, bytes={peer.InFlightBytes}\");", title="Диагностика не заменяет барьер чтения") + p(
        "Commit минус applied показывает локальную очередь применения. Хвост минус подтверждённый MatchIndex адресата показывает отставание репликации. Частые изменения term указывают на таймеры, хранилище или сеть. Offset отправки/приёма снимка объясняет, почему отставший последователь ещё не вернулся к обычным AppendEntries. Status — опубликованное диагностическое представление, а не атомарный запрос приложения.") + excerpt("IntegrationRecipes.cs", "logging") + table(
        ["Источник", "Что собирать", "Единицы и область"], [
            ["ILoggerFactory", "Роли, term, конфигурации/образы, ошибки и неуспешные RPC.", "Провайдеры логов задаёт хост; payload не пишется."],
            ["Meter / ActivitySource", "<code>Raft.Net8</code>", "Теги raft.group, raft.node, raft.peer/outcome."],
            ["Индексы", "raft.commit.index, raft.applied.index, raft.replication.lag", "Позиции записей или отставание в записях."],
            ["Очереди и бюджеты", "raft.proposals.pending, raft.reads.pending, raft.uncommitted.bytes", "Количество и байты."],
            ["Гистограммы времени", "raft.proposal.duration, raft.persistence.duration, raft.storage.commit.duration, raft.apply.duration", "Секунды. Commit включает работу/flush DBreeze, а не один системный вызов."],
            ["Completion / failures", "Цепочка исходного исключения и контекст рестарта/завершения хоста.", "При storage/app fault участие прекращается."]]) + p(
        "Экспортёры и listeners регистрируются в хосте; сохраняйте измерения группы/узла. Медленный синхронный логгер или callback не должен блокировать горячий путь. Ошибки диагностики изолированы и считаются отдельно; они не должны скрывать исходную ошибку хранения. Вне библиотеки собирайте RSS/GC процесса, CPU, свободное место, хвосты дискового Commit и состояние сети."))

    add("hosting", "Переход от упражнения к сервису", ol(
        "Разместите голосующих в разных доменах отказа и на разных дисках. Три процесса на ноутбуке показывают протокол, но не отказоустойчивость к потере машины.",
        "Назначьте стабильные идентичности и постоянные каталоги. При рестартах сохраняйте связку ID/данные и исключите одновременно активные клоны.",
        "Обеспечьте доступные маршруты, firewall/TLS и совместимые пределы у всех участников.",
        "Создайте публичный слой маршрутизации к лидеру, ограничение admission, бизнес-валидацию и постоянные результаты запросов.",
        "Определяйте readiness по здоровому восстановленному состоянию и успешному чтению/записи через кворум, а не факту запуска процесса.",
        "Подключите Completion к супервизору, закрывайте транспорт до хранилища и отрепетируйте рестарт/restore до рабочего трафика.") + p(
        "Учебный процесс слушает только loopback и принимает локальный stdin. У него намеренно нет административного production HTTP endpoint. Ключи <code>--base-port</code>, <code>--data</code>, <code>--single</code> и <code>--memory</code> принадлежат этому примеру, а не RaftOptions и не командной строке самой библиотеки.") + p(
        "В контейнерах и службах нужны постоянные тома с проверенными свойствами хранения. Нельзя выдавать каждому новому контейнеру пустую базу, оставляя прежнюю голосующую идентичность. Разделяйте liveness и readiness: процесс без кворума может быть жив, но не способен обслужить сильные чтения/записи. Постоянный рестарт не возвращает отсутствующих участников.") + p(
        "Сохраняйте совместимый формат команд и приложения на всех репликах, включая replay снимков. Изменение смысла ранее подтверждённых команд во время rollout может привести к расхождению бизнес-состояний даже при правильном журнале Raft. Библиотека не версионирует и не мигрирует ваш обработчик автоматически."))

    add("recovery", "Резервные копии, восстановление и замена", h("Обычный рестарт") + p(
        "По возможности корректно остановитесь, сохраните те же идентичности и каталоги, затем запускайтесь через CreateAsync. Восстановление проверяет записи с контрольными суммами, постоянные границы и checkpoint приложения, завершает незаконченный переход снимка и при необходимости применяет/догоняет историю. Чистая остановка полезна, но дисковый путь рассчитан и на аварийное завершение процесса при выполнении предпосылок хранения.") + h("Резервная копия") + p(
        "Простой эксплуатационный базис — согласованная копия остановленного узла: база журнала, корень приложения и репозиторий снимков. Перед обычным копированием каталогов закройте все engine. Сохраните дескрипторы, указатели поколений и идентичности. Живое копирование нескольких файлов таблиц само по себе не гарантирует согласованности. Средства backup DBreeze требуют общего плана с отдельными корнями приложения/образов.") + h("Одна реплика потеряна, кворум исправен") + p(
        "Сохраните неисправные файлы для разбора. Предпочитайте поддерживаемую замену: заранее известный новый ID → learner → догоняние → повышение → удаление старого, сохраняя кворум. Не стирайте действующего voter и не возвращайте его пустым под прежним ID. Для restore остановленной реплики нужна копия/история, совместимая с оставшейся работающей группой.") + h("Авария всей группы") + p(
        "Восстановите достаточное число прежних идентичностей из согласованных копий, содержащих необходимую подтверждённую историю. Перед открытием клиентского трафика проверьте ReadIndex, запись/чтение и catch-up. Возраст backup ограничивает восстанавливаемые подтверждённые записи. Нет безопасного API quorum-reset/force-new-cluster, которое само выведет утраченную историю из одного старого узла.") + callout(
        "Контрольная сумма обнаруживает, но не лечит любую потерю", "Ошибка CRC или несовпадение checkpoint приложения/журнала — повод остановиться, исследовать и восстановиться, а не редактировать запись до успешного старта. Долговечность опирается на выполнение flush со стороны ОС/устройства. Программные fault-тесты не доказывают поведение при физическом отключении питания.", "warn") + p(
        source_link("docs/OPERATIONS.md", "Подробный runbook восстановления, backup и миграций")))

    add("upgrades", "Формат диска, wire и приложения — разные версии", table(
        ["Ось версии", "Текущий выбор", "Правило обновления"], [
            ["Runtime/API", "Проект net8.0 в RaftNet8/.", "Исторические Framework/Standard-базы не являются входом современной миграции."],
            ["Дисковый формат", "Явный UnifiedTableV4 + wire3 для новых кластеров; v2/v3 — совместимость.", "Конвертера v2/v3→v4 нет. Ниже описан прежний путь v2→v3."],
            ["Сетевой wire", "Версия 3 для новых v4-кластеров.", "Смешивание wire1/2/3 отклоняется; v4 требует wire3."],
            ["Лимиты wire2", "Совместимые MaxReplicationBytes/MaxCommandBytes/кадры.", "Старый wire2 receiver может отклонять новые более крупные значения по умолчанию."],
            ["Формат приложения/образов", "Стабильный версионированный обработчик и ApplicationId.", "Явная прикладная миграция; инструмент Raft не угадывает схему."]]) + callout("V4 — отдельный новый режим", "Команда ниже относится только к прежнему v2→v3 и не создаёт v4. Старые данные сохраните; новой группе wire3 нужны новые каталоги.") + code(
        "dotnet run --project tools/Raft.Migrate -c Release -- --v2-to-v3 <source-db> <new-db> <group> <node> <initial-voter-list>", "shell", "Из RaftNet8/; вся группа и все engine должны быть остановлены") + p(
        "Программный API: <code>RaftStorageMigration.CopyV2ToV3(source, destination, options)</code>. Назначение должно отсутствовать и находиться вне источника. Инструмент проверяет, копирует и конвертирует каталог базы, затем завершает его публикацию. Незаконченная цель не должна запускаться. Бизнес-таблицы внутри этого DB-каталога копируются без изменения; соседние корни приложения и снимков не копируются — перенесите их отдельно при остановленных engine. Этот путь отклоняет reparse points и вынесенные наружу таблицы.") + p(
        "Сохраните прежние группу/узел и восстановленный состав. Проверьте manifest и индексы, запустите кворум, выполните чтение/запись, catch-up, снимки и ещё один рестарт, затем откройте трафик. После новых подтверждённых записей прежние каталоги устаревают и не являются безопасным rollback.") + callout(
        "Новые крупные пакеты wire2 требуют совместимых узлов", "При rolling-обновлении бинарников со старым wire2 задайте каждому новому узлу MaxReplicationBytes=262144 либо старый MaxAppendBytes группы и сохраняйте его до конца rollout. Увеличивайте лимит только после совместимости всех получателей. Если размеры отправки и приёма нельзя менять отдельно, согласуйте stop/configure/restart. V2/v3 диска используют один wire2; одно изменение лимита кадра не требует конвертации данных.", "warn") + p(
        "Wire1 требует выключенного pre-vote, отсутствия снимков и старого байтового бюджета; современные ReadIndex, transfer и membership-control недоступны. Совместимые fixtures не делают базы старых pre-.NET-8 проектов автоматически мигрируемыми. Отдельную процедуру v1→v2 из runbook применяйте только к поддерживаемому формату <code>raft8-v1</code>."))

    add("troubleshooting", "Типичные проблемы и их смысл", table(
        ["Симптом", "Вероятное объяснение", "Полезное действие"], [
            ["Нет лидера / непрерывные выборы", "Нет связанного кворума, ошибочны группа/маршруты, несовместимы пределы или малы таймеры.", "Проверьте активный состав, сеть/TLS, хвосты диска и status всех узлов."],
            ["Запись прошла, local последователя старый", "Отстают применение/уведомление commit; local допускает старое значение.", "ReadIndex и запрос того же лидера либо явный контракт stale read."],
            ["NotLeader без подсказки", "Выборы, разделение сети или неизвестный актуальный лидер.", "Обновляйте discovery; повторяйте ограниченно с тем же ID."],
            ["Таймаут клиента", "Admission, репликация или применение не уложились в дедлайн.", "Считайте исход неопределённым; запросите/повторите тот же замысел."],
            ["UncommittedLogLimitException", "Прогресс кворума не освобождает неподтверждённый бюджет.", "Верните кворум/прогресс, ограничьте производителей, примените backoff."],
            ["Слишком большая команда/кадр", "Превышен размер кодирования или лимиты участников различаются.", "Учитывайте JSON и согласуйте связанные приёмные/оконные бюджеты."],
            ["Отказ identity/layout/checkpoint при старте", "Не тот каталог/конструктор, незаконченная миграция или несогласованный app/log backup.", "Остановитесь; изучите исходную ошибку и восстановите согласованные файлы."],
            ["Файл занят / owner.lock", "Другой процесс владеет тем же engine, корнем приложения или образов.", "Один владелец, разные корни узлов; не удаляйте lock работающего владельца."],
            ["Снимок busy", "Идёт построение, retention или приём/установка.", "Дождитесь прогресса и повторите; отличайте busy от ошибки Completion."],
            ["Растёт память", "Бизнес/дедупликационные записи, неограниченные ожидающие клиенты, кэши DBreeze или неактивная политика снимков.", "Измеряйте категории; лимит кэша журнала не ограничивает весь RAM/диск."]]) + p(
        "Сохраняйте полную исходную ошибку, status/состав, идентичности, версии runtime/зависимостей и контекст диска/сети. Не пишите секретные команды в лог только ради разбора репликации. Если Completion завершился ошибкой, прекратите участие и сохраните данные до попыток исправления."))

    add("sources", "Исходники примера и повторяемые упражнения", p(
        "Соседний проект C# является источником встроенных фрагментов. Он ссылается на настоящую библиотеку и компилирует startup, приложение, TLS, ограниченную нагрузку и рецепты membership. Запускаемый процесс упражняет запись, чтение, дедупликацию первого результата, снимки и освобождение ресурсов. Административным рецептам нужен правильно подготовленный контекст хоста; это не скрытые дополнительные команды CLI.") + table(
        ["Файл", "Назначение"], [
            ['<a href="examples/TutorialNode/TutorialNode.csproj">TutorialNode.csproj</a>', "Ссылка на исходный net8.0-проект и наследуемая политика пакетов."],
            ['<a href="examples/TutorialNode/TutorialSettings.cs">TutorialSettings.cs</a>', "Аргументы примера, общий состав, endpoints и учебные таймеры."],
            ['<a href="examples/TutorialNode/Program.cs">Program.cs</a>', "Запуск, консольные API-вызовы, контроль Completion и остановка."],
            ['<a href="examples/TutorialNode/BookState.cs">BookState.cs</a>', "Версионированные команды, постоянная дедупликация, дисковое и RAM-приложения."],
            ['<a href="examples/TutorialNode/IntegrationRecipes.cs">IntegrationRecipes.cs</a>', "Компилируемые части интеграции; параметры политики задаёт ваш хост."]]) + h("Проверьте понимание") + ol(
        "Почему единственный уцелевший узел из трёх может показать значение, но не безопасно подтвердить новую запись?",
        "Что успех ProposeAsync говорит о приложении лидера и чего не обещает о применении последователями?",
        "Какие три корня должны входить в согласованный backup учебного узла?",
        "Что остаётся после выхода RAM-процесса и чем опасен возврат voter, забывшего прошлое?",
        "Зачем при повторе сохранять ID и payload и почему результаты запросов могут вырасти больше таблицы значений?",
        "Какие настройки нужно менять вместе ради команды на 1 МиБ и что произойдёт со старым получателем маленьких кадров?") + p(
        "Для повторения процессных проверок после сборки запустите проверочный скрипт. Он запускает только собственные учебные процессы и сохраняет их логи/данные в <code>.artifacts/human-tutorial/</code>. Проверяются смена лидера, отказ меньшинству, снимки, постоянный рестарт/дедупликация и сброс памяти. Это функциональный опыт, а не замер серверной ёмкости.") + code(
        "python -X utf8 -B docs/human/tutorial/verify_examples.py", "shell") + p(
        "После изменения текста или фрагментов исходников HTML пересобирается Python-скриптом. Обоим скриптам достаточно стандартной библиотеки. Для чтения готовых книг Python не нужен.") + code(
        "python -X utf8 -B docs/human/tutorial/build.py", "shell") + "<details><summary>Полный исходник приложения: BookState.cs</summary>" + code(
        (EXAMPLES / "BookState.cs").read_text(encoding="utf-8"), title="BookState.cs") + "</details><details><summary>Полный исходник процесса: Program.cs</summary>" + code(
        (EXAMPLES / "Program.cs").read_text(encoding="utf-8"), title="Program.cs") + "</details>")

    add("reference", "Словарь, границы поддержки и ссылки", table(
        ["Термин", "Смысл в этой библиотеке"], [
            ["Term / index", "Эпоха выборов / положение записи в упорядоченном журнале."],
            ["Commit / apply", "Согласованная постоянная история / её выполнение локальным приложением."],
            ["Checkpoint", "Постоянные применённые index/term, атомарно соответствующие бизнес-эффектам."],
            ["Voter / learner / known peer", "Голосующий для кворума / реплицируемый неголосующий / известная транспортная идентичность."],
            ["Snapshot / generation", "Неизменяемый образ префикса / экземпляр прикладной базы, выбранный атомарным указателем."],
            ["ReadIndex", "Свежий контекст кворума и барьер применения лидера без новой записи журнала."],
            ["Fail-stop", "Прекращение участия после неопределённой ошибки исполнения storage/app."],
            ["Backpressure", "Ограничение принятой работы и ожидание/отказ/повтор вместо бесконечного роста очередей."]]) + p(
        "Эксплуатационная область — crash/recovery для non-Byzantine развёртывания, обычно в одном регионе. Нет joint consensus, lease reads, автоматической переадресации внутри embedded ядра, гарантий межрегиональной ёмкости и небезопасного сброса кворума. Внешние эффекты требуют прикладного протокола. RAM-хранилище — возможность одноразового опыта, а не замена стабильному хранению.") + ul(
        source_link("src/Raft/RaftOptions.cs", "RaftOptions: исполняемые значения и проверки"),
        source_link("src/Raft/RaftNode.cs", "RaftNode: жизненный цикл и операции лидера"),
        source_link("src/Raft/Storage/DBreezeLogStorage.cs", "Журнал DBreeze: конструкторы и фабрика RAM"),
        source_link("docs/CONFIGURATION.md", "Справочник параметров и диагностики"),
        source_link("docs/OPERATIONS.md", "Эксплуатационный runbook и миграции"),
        source_link("docs/ARCHITECTURE.md", "Архитектура и форматы хранения"),
        source_link("docs/VALIDATION.md", "Выполненные проверки и пределы их доказательности"),
        '<a href="../../../../_docs/raft_skill.md">Инструкция интеграции из репозитория</a>',
        '<a href="../../../../_docs/llm/skill/DBreeze_skill.md">Сохранённый справочник транзакций DBreeze</a>',
        '<a href="https://raft.github.io/raft.pdf">Ongaro и Ousterhout: расширенная статья Raft</a> — теория алгоритма; публичные контракты этой реализации задают её исходники и runbook.',
        '<a href="https://github.com/hhblaze/DBreeze">Основной репозиторий DBreeze</a>.') + p(
        "Издание описывает текущий net8.0 API и значения по умолчанию на 15 ноября 2026 года. Учебные таймеры, пути и синтаксис команд отмечены отдельно. Перед сочетанием с другой версией бинарника перепроверьте исходники и инструкции обновления."))

    return book
